 import React, { useState, useEffect } from 'react'
import { useAuth } from '../contexts/AuthContext'
import { Link } from 'react-router-dom'
import { 
  Trophy, 
  BarChart3, 
  Target, 
  Calendar, 
  Sparkles,
  Loader
} from 'lucide-react'
import { getTodaysMatches, formatMatch, COMPETITIONS } from '../services/footballApi'

export default function Home() {
    const { profile } = useAuth()
    const [matches, setMatches] = useState([])
    const [loading, setLoading] = useState(true)

    useEffect(() => {
        loadTodayMatches()
    }, [])

    const loadTodayMatches = async () => {
        setLoading(true)
        try {
            let matchesData = await getTodaysMatches(COMPETITIONS.PREMIER_LEAGUE)
            if (matchesData.length === 0) {
                matchesData = await getTodaysMatches(COMPETITIONS.LA_LIGA)
            }
            if (matchesData.length === 0) {
                matchesData = await getTodaysMatches(COMPETITIONS.BUNDESLIGA)
            }
            const formattedMatches = matchesData.slice(0, 6).map(m => formatMatch(m))
            setMatches(formattedMatches)
        } catch (error) {
            console.error('Error loading today matches:', error)
            setMatches([])
        } finally {
            setLoading(false)
        }
    }

    return (
        <div>
            {/* Welcome Banner */}
            <div className="bg-gray-100 dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-6 md:p-8 mb-8 transition-colors duration-200">
                <h1 className="text-2xl md:text-3xl font-bold text-gray-800 dark:text-white flex items-center gap-3">
                    <Sparkles className="text-gray-600 dark:text-gray-400" size={28} />
                    Welcome, {profile?.full_name || 'Predictor'}!
                </h1>
                <p className="text-gray-500 dark:text-gray-400 mt-2">Predict matches, earn points, and climb the leaderboard</p>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 md:gap-6 mb-8">
                <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 p-6 text-center transition-colors duration-200">
                    <Trophy className="w-10 h-10 text-gray-700 dark:text-gray-300 mx-auto mb-2" />
                    <h3 className="font-bold text-gray-700 dark:text-gray-300">Your Points</h3>
                    <p className="text-2xl font-bold text-gray-900 dark:text-white">{profile?.points || 0}</p>
                </div>
                <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 p-6 text-center transition-colors duration-200">
                    <BarChart3 className="w-10 h-10 text-gray-700 dark:text-gray-300 mx-auto mb-2" />
                    <h3 className="font-bold text-gray-700 dark:text-gray-300">Predictions</h3>
                    <p className="text-2xl font-bold text-gray-900 dark:text-white">{profile?.predictions_count || 0}</p>
                </div>
                <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 p-6 text-center transition-colors duration-200">
                    <Target className="w-10 h-10 text-gray-700 dark:text-gray-300 mx-auto mb-2" />
                    <h3 className="font-bold text-gray-700 dark:text-gray-300">Accuracy</h3>
                    <p className="text-2xl font-bold text-gray-900 dark:text-white">{profile?.accuracy || 0}%</p>
                </div>
            </div>

            {/* Today's Matches */}
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 p-6 transition-colors duration-200">
                <h2 className="text-xl font-bold text-gray-700 dark:text-gray-300 mb-4 flex items-center gap-2">
                    <Calendar size={20} /> Today's Matches
                </h2>
                
                {loading ? (
                    <div className="text-center py-8">
                        <Loader className="w-8 h-8 text-gray-300 dark:text-gray-600 animate-spin mx-auto" />
                        <p className="text-gray-400 dark:text-gray-500 mt-2">Loading matches...</p>
                    </div>
                ) : matches.length === 0 ? (
                    <div className="text-center py-8 text-gray-400 dark:text-gray-500">
                        <Calendar className="w-12 h-12 text-gray-200 dark:text-gray-700 mx-auto mb-2" />
                        <p>No matches scheduled for today</p>
                        <p className="text-sm mt-1">Check back later for upcoming games</p>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        {matches.map((match) => {
                            const homeName = match.homeTeam?.name || 'Unknown'
                            const awayName = match.awayTeam?.name || 'Unknown'
                            const homeCrest = match.homeTeam?.crest
                            const awayCrest = match.awayTeam?.crest
                            const ai = match.aiPrediction || {}
                            
                            let resultText = 'Draw'
                            if (ai.result?.home > ai.result?.draw && ai.result?.home > ai.result?.away) resultText = 'Home Win'
                            else if (ai.result?.away > ai.result?.home && ai.result?.away > ai.result?.draw) resultText = 'Away Win'

                            const matchDate = match.kickoff ? new Date(match.kickoff) : new Date()
                            const timeStr = matchDate.toLocaleTimeString('en-US', { 
                                hour: '2-digit', 
                                minute: '2-digit' 
                            })

                            return (
                                <div 
                                    key={match.id} 
                                    className="bg-gray-50 dark:bg-gray-700 rounded-lg p-3 border border-gray-100 dark:border-gray-600 flex items-center justify-between transition-colors duration-200"
                                >
                                    <div className="flex items-center gap-3 flex-1">
                                        <div className="flex items-center gap-2">
                                            {homeCrest ? (
                                                <img src={homeCrest} alt={homeName} className="w-6 h-6 object-contain" />
                                            ) : (
                                                <span className="text-xl">{match.homeTeam?.badge || '⚽'}</span>
                                            )}
                                            <span className="font-medium text-gray-800 dark:text-gray-200 text-sm">{homeName}</span>
                                        </div>
                                        <span className="text-gray-400 dark:text-gray-500 text-xs">vs</span>
                                        <div className="flex items-center gap-2">
                                            <span className="font-medium text-gray-800 dark:text-gray-200 text-sm">{awayName}</span>
                                            {awayCrest ? (
                                                <img src={awayCrest} alt={awayName} className="w-6 h-6 object-contain" />
                                            ) : (
                                                <span className="text-xl">{match.awayTeam?.badge || '⚽'}</span>
                                            )}
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-3 text-xs text-gray-400 dark:text-gray-500">
                                        <span>{timeStr}</span>
                                        <span className="font-semibold text-gray-600 dark:text-gray-400">{resultText}</span>
                                        <span>{ai.confidence || 0}%</span>
                                    </div>
                                </div>
                            )
                        })}
                    </div>
                )}
            </div>
        </div>
    )
}
